import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, time, uniform, texture, normalMap, displacementMap, attribute } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Text content bridging
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMap = {};
  for (const item of items) {
    if (item.role === 'kicker') textMap.kicker = item.text;
    if (item.role === 'headline') textMap.headline = item.text;
    if (item.role === 'body') textMap.body = item.text;
    if (item.role === 'caption') textMap.caption = item.text;
  }

  // Fallback text
  textMap.kicker ??= 'NOVA ATELIER / GENEVA';
  textMap.headline ??= 'Time, Machined.';
  textMap.body ??= 'Every case begins as a single billet of 904L steel.';
  textMap.caption ??= 'CALIBRE NA-01 / 72 HOUR RESERVE';

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  // Main plate: tessellated plane with displacement
  const planeGeo = new THREE.PlaneGeometry(4.0, 2.5, 64, 64);

  // Load textures
  let imageTex = null;
  let depthTex = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imageTex = tex;
      imageTex.colorSpace = THREE.SRGBColorSpace;
      plateMat.colorNode = texture(imageTex);
      plateMat.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex = tex;
      depthTex.colorSpace = THREE.NoColorSpace;
      // Displacement node
      const dispIntensity = uniform(0.18);
      plateMat.displacementNode = texture(depthTex).r.mul(dispIntensity).sub(dispIntensity.mul(0.5));
      plateMat.needsUpdate = true;
    });
  }

  // Filmic grade: black lift, highlight shoulder, midtone contrast +12%, desaturation -8% with red preserved
  const filmicGrade = (texColor) => {
    // Lift blacks toward #0d0d12
    const liftColor = vec3(0.05, 0.05, 0.07);
    const lifted = mix(liftColor, texColor, smoothstep(0, 0.3, texColor));

    // Shoulder highlights toward paper #e8ecf2
    const paperColor = vec3(0.91, 0.93, 0.95);
    const shouldered = mix(lifted, paperColor, smoothstep(0.7, 1.0, lifted));

    // Midtone contrast +12%
    const midMask = smoothstep(0.3, 0.7, shouldered);
    const contrast = mix(shouldered, shouldered.sub(0.5).mul(1.12).add(0.5), midMask);

    // Desaturation -8% with red preserved
    const gray = contrast.x.mul(0.299).add(contrast.y.mul(0.587)).add(contrast.z.mul(0.114));
    const desat = mix(gray, contrast, vec3(1.0, 0.92, 0.92)); // Keep red, desaturate G/B

    return desat;
  };

  const plateMat = new MeshBasicNodeMaterial({
    colorNode: filmicGrade(texture(uv().xy, 0)),
    side: THREE.FrontSide,
    toneMapped: true,
  });

  const plateGeometryNode = planeGeo.clone();
  const plateMesh = new THREE.Mesh(planeGeo, plateMat);
  plateMesh.name = 'plate';
  group.add(plateMesh);

  // Plate entrance: opacity 0 -> 1 over 500ms cubic-bezier(0.25,0.46,0.45,0.94)
  plateMesh.material.opacity = 0;
  plateMesh.material.transparent = true;
  gsap.to(plateMesh.material, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic.inOut',
  });

  // Caption block: stacked on bottom-left
  const captionGroup = new THREE.Group();
  captionGroup.position.set(-1.8, -1.0, 0.01); // bottom-left with padding
  group.add(captionGroup);

  // Kicker
  const kickerText = ctx.fontAtlas.createText(textMap.kicker, {
    fontSize: 9,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 0.12 * 9,
  });
  kickerText.position.y = 0.3;
  captionGroup.add(kickerText);

  // Headline
  const headlineText = ctx.fontAtlas.createText(textMap.headline, {
    fontSize: 34,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 400,
  });
  headlineText.position.y = -0.1;
  captionGroup.add(headlineText);

  // Accent hairline: 0.75w x 0.02h in #ff2a38 emissive intensity 1.8
  const hairlineGeo = new THREE.PlaneGeometry(0.75, 0.02);
  const hairlineMat = new THREE.MeshBasicMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.8,
  });
  const hairline = new THREE.Mesh(hairlineGeo, hairlineMat);
  hairline.position.y = -0.25;
  hairline.position.z = 0.01;
  captionGroup.add(hairline);

  // Body text
  const bodyText = ctx.fontAtlas.createText(textMap.body, {
    fontSize: 13,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 400,
  });
  bodyText.position.y = -0.45;
  captionGroup.add(bodyText);

  // Caption: smaller secondary
  const captionText = ctx.fontAtlas.createText(textMap.caption, {
    fontSize: 9,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 0.12 * 9,
  });
  captionText.position.y = -0.7;
  captionGroup.add(captionText);

  // Caption block rise-in: y +0.4 -> 0 over 700ms cubic-bezier(0.215,0.61,0.355,1) starting 120ms after plate
  captionGroup.position.y = -0.6; // Start position (+0.4 from -1.0)
  gsap.to(captionGroup.position, {
    y: -1.0,
    duration: 0.7,
    ease: 'power3.out',
    delay: 0.12,
  });

  // Apply parallax-scroll primitive
  let primitiveCleanup = null;
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    for (const prim of config.cinematicPrimitives) {
      if (prim.name === 'parallax-scroll') {
        const result = ctx.primitives['parallax-scroll'](group, prim.params ?? { intensity: 0.35 });
        primitiveCleanup = result.cleanup;
        break;
      }
    }
  }

  // Backdrop scrim gradient plane (behind the plate)
  const scrimGeo = new THREE.PlaneGeometry(7, 6);
  const scrimMat = new THREE.MeshBasicMaterial({
    color: colors.background,
    side: THREE.BackSide,
  });
  // Gradient from transparent at top to opaque at bottom
  const canvas = document.createElement('canvas');
  canvas.width = 1;
  canvas.height = 256;
  const ctx2d = canvas.getContext('2d');
  const grad = ctx2d.createLinearGradient(0, 0, 0, 256);
  grad.addColorStop(0.45, 'rgba(11, 11, 16, 0)');
  grad.addColorStop(1, 'rgba(11, 11, 16, 0.92)');
  ctx2d.fillStyle = grad;
  ctx2d.fillRect(0, 0, 1, 256);

  const scrimTex = new THREE.CanvasTexture(canvas);
  scrimMat.map = scrimTex;
  scrimMat.transparent = true;

  const scrimMesh = new THREE.Mesh(scrimGeo, scrimMat);
  scrimMesh.position.z = -2.5;
  group.add(scrimMesh);

  // Cleanup
  group.userData.cleanup = () => {
    if (primitiveCleanup) primitiveCleanup();
    gsap.killTweensOf([plateMesh.material, captionGroup.position]);
    planeGeo.dispose();
    plateMat.dispose();
    hairlineMat.dispose();
    scrimMat.dispose();
    scrimTex.dispose();
  };

  return group;
}
